import React from 'react';
import jStat from 'jstat';
import {AbsoluteFill, Composition, interpolate, registerRoot, useCurrentFrame} from 'remotion';
import story from '../../normal/storyboard.json';
import {NormalChart} from './normal-chart.jsx';
import {FormulaTransition} from './normal-formula.jsx';
import 'katex/dist/katex.min.css';
import './style.css';

const clamp = {extrapolateLeft: 'clamp', extrapolateRight: 'clamp'};

export function NormalStandardization() {
  const frame = useCurrentFrame();
  const time = frame / story.fps;
  const progress = event => interpolate(frame, story.events[event].map(time => time * story.fps), [0, 1], clamp);
  const phase = story.phases.find(phase => time >= phase.start && time < phase.end) ?? story.phases.at(-1);
  const sigma = story.sigma - progress('narrow') + 1.6 * progress('widen') - 0.6 * progress('restore');
  const selected = 6 + 8 * progress('scan') - 2 * progress('settle');
  const standardized = (selected - story.mean) / story.sigma;
  const shade = -4 + 5 * progress('shade');
  const tail = progress('tail');
  const showPoint = time >= story.events.scan[0];
  return <AbsoluteFill className="video-stage" style={{background: '#fcfcfd', color: '#182d28'}}>
    <header style={{position: 'absolute', inset: '0 64px auto', height: 78, borderBottom: '1px solid #dce5df', display: 'flex', alignItems: 'center', justifyContent: 'space-between'}}>
      <h1 style={{fontFamily: 'VideoSerif', fontSize: 38, fontWeight: 400, margin: 0}}>La normal: de X a Z</h1>
      <span style={{fontSize: 19, color: '#596860'}}>REMOTION</span>
    </header>
    <FormulaTransition story={story} />
    <div style={{position: 'absolute', top: 190, width: '100%', textAlign: 'center', fontSize: 23, color: '#596860'}}>{phase.title}</div>
    <div style={{position: 'absolute', top: 235, left: 60}}>
      <NormalChart mean={story.mean} sigma={sigma} selected={selected} shade={shade} tail={tail} draw={progress('draw')} showPoint={showPoint} showWidth={phase.id==='width'} />
    </div>
    <div style={{position: 'absolute', top: 235, left: 670, opacity: progress('standardize')}}>
      <NormalChart mean={0} sigma={1} selected={standardized} shade={shade} tail={tail} standard showPoint={showPoint} />
    </div>
    <div style={{position: 'absolute', left: 640, top: 239, height: 274, borderLeft: '1px solid #dce5df'}} />
    {[{left: 60, mean: story.mean, sigma}, {left: 670, mean: 0, sigma: 1}].map((parameters, index) => <div key={index}
      style={{position: 'absolute', left: parameters.left, top: 539, width: 550, textAlign: 'center', fontSize: 23, color: '#596860', opacity: index ? progress('standardize') : 1}}>
      <div>media = {parameters.mean} &nbsp; sigma = {parameters.sigma.toFixed(2)}</div>
      <div style={{fontSize: 22, marginTop: 12}}>Area total = 1</div>
    </div>)}
    {time >= story.events.shade[0] && <div style={{position: 'absolute', top: 568, left: 510, width: 260, textAlign: 'center', fontSize: 26, color: tail ? '#bf5547' : '#008b70'}}>
      {tail ? '0.8413 + 0.1587 = 1' : jStat.normal.cdf(shade, 0, 1).toFixed(4)}
    </div>}
    <footer className="caption-band" style={{background: '#182d28', borderTop: 0}}>
      <div className="caption" style={{fontSize: 25}}>{phase.caption}</div>
    </footer>
  </AbsoluteFill>;
}

registerRoot(() => <Composition id="NormalStandardization" component={NormalStandardization}
  width={story.width} height={story.height} fps={story.fps} durationInFrames={story.frames} />);

import React from 'react';
import jStat from 'jstat';

const green = '#008b70';
const coral = '#bf5547';
const baseline = 220;
const ordinate = density => baseline - density * 400;

export function NormalChart({mean, sigma, selected, shade, tail, draw = 1, standard = false, showPoint = false, showWidth = false}) {
  const domain = standard ? [-4, 4] : [2, 18];
  const abscissa = value => 52 + (value - domain[0]) / (domain[1] - domain[0]) * 470;
  const density = value => jStat.normal.pdf(value, mean, sigma);
  const points = (start, end) => Array.from({length: 81}, (_, index) => {
    const value = start + (end - start) * index / 80;
    return `${abscissa(value)},${ordinate(density(value))}`;
  }).join(' L');
  const area = (start, end) => `M${abscissa(start)},${baseline} L${points(start, end)} L${abscissa(end)},${baseline} Z`;
  const edge = Math.max(domain[0], Math.min(domain[1], mean + sigma * shade));
  const threshold = standard ? 1 : 12;
  return <svg viewBox="0 0 550 295" width="550" height="295" aria-label={standard ? 'Normal estandar' : 'Normal original'}>
    <text x="52" y="24" fontSize="19" fill="#596860">Densidad</text>
    {[0.1, 0.2, 0.3, 0.4].map(value => <line key={value} x1="52" x2="522" y1={ordinate(value)} y2={ordinate(value)} stroke="#e3e9e5" />)}
    {shade > -4 && <path d={area(domain[0], edge)} fill={green} opacity={0.3 * (1 - tail)} />}
    {tail > 0 && <path d={area(threshold, domain[1])} fill={coral} opacity={0.3 * tail} />}
    <path d={`M${points(...domain)}`} fill="none" stroke={green} strokeWidth="4" pathLength="1" strokeDasharray="1" strokeDashoffset={1 - draw} />
    <path d={`M52,${ordinate(0.45)} V${baseline} H530`} fill="none" stroke="#596860" strokeWidth="2" />
    {[domain[0], mean, domain[1]].map(value => <g key={value}>
      <line x1={abscissa(value)} x2={abscissa(value)} y1={baseline} y2={baseline + 7} stroke="#596860" />
      <text x={abscissa(value)} y={baseline + 29} textAnchor="middle" fontSize="20" fill="#182d28">{value}</text>
    </g>)}
    {showPoint && <g>
      <line x1={abscissa(selected)} x2={abscissa(selected)} y1={baseline} y2={ordinate(density(selected))} stroke={coral} strokeWidth="2" />
      <circle cx={abscissa(selected)} cy={ordinate(density(selected))} r="6" fill={coral} />
      <text x="475" y="24" textAnchor="end" fontSize="26" fill={coral}>{standard ? 'z' : 'x'} = {selected.toFixed(2)}</text>
    </g>}
    {showWidth && <path d={`M${abscissa(mean-sigma)},263 v7 H${abscissa(mean+sigma)} v-7`} fill="none" stroke={green} strokeWidth="2" />}
    <text x="527" y="274" textAnchor="end" fontSize="24" fill="#182d28">{standard ? 'Z' : 'X'}</text>
  </svg>;
}

import React, {useEffect, useState} from 'react';
import katex from 'katex';
import {cancelRender, continueRender, delayRender, interpolate, useCurrentFrame} from 'remotion';

const clamp = {extrapolateLeft: 'clamp', extrapolateRight: 'clamp'};
const render = tex => katex.renderToString(tex, {throwOnError: true, output: 'html'});

function tokens(parts, widths) {
  const occurrences = new Map();
  let cursor = -parts.reduce((sum, tex) => sum + widths[tex] + 15, 0) / 2;
  return parts.map(tex => {
    const occurrence = occurrences.get(tex) ?? 0;
    occurrences.set(tex, occurrence + 1);
    const token = {id: `${tex}:${occurrence}`, tex, center: cursor + widths[tex] / 2};
    cursor += widths[tex] + 15;
    return token;
  });
}

export function FormulaTransition({story}) {
  const frame = useCurrentFrame();
  const [widths, setWidths] = useState(null);
  const [handle] = useState(() => delayRender('Measure formula tokens'));
  useEffect(() => {
    let active = true;
    const fonts = ['VideoSans', 'VideoSerif', 'KaTeX_Main', 'KaTeX_Math', 'KaTeX_Size1', 'KaTeX_Size2', 'KaTeX_Size3', 'KaTeX_Size4'];
    Promise.all(fonts.map(font => document.fonts.load(`40px ${font}`)))
      .then(() => document.fonts.load('italic 40px KaTeX_Math'))
      .then(() => document.fonts.ready).then(() => {
        const element = document.createElement('div');
        element.className = 'formula';
        Object.assign(element.style, {position: 'fixed', visibility: 'hidden', display: 'inline-block', fontSize: '40px'});
        document.body.appendChild(element);
        const measured = {};
        try {
          for (const tex of new Set(Object.values(story.formulas).flat())) {
            element.innerHTML = render(tex);
            measured[tex] = element.getBoundingClientRect().width;
          }
        } finally {element.remove();}
        if (active) {setWidths(measured); continueRender(handle);}
      }).catch(cancelRender);
    return () => {active = false;};
  }, [handle, story]);
  if (!widths) return null;
  const changes = Object.keys(story.formulas).filter(name => name in story.events);
  const index = changes.findLastIndex(name => frame >= story.events[name][0] * story.fps);
  const current = index < 0 ? 'density' : changes[index];
  const previous = index < 1 ? 'density' : changes[index - 1];
  const progress = index < 0 ? 1 : interpolate(frame, story.events[current].map(time => time * story.fps), [0, 1], clamp);
  const before = new Map(tokens(story.formulas[previous], widths).map(token => [token.id, token]));
  const after = new Map(tokens(story.formulas[current], widths).map(token => [token.id, token]));
  const totalWidth = Math.max(...[previous, current].map(name => story.formulas[name].reduce((sum, tex) => sum + widths[tex] + 15, 0)));
  const scale = Math.min(1, 1140 / totalWidth);
  return <div className="formula" style={{position: 'absolute', left: '50%', top: 134, width: 0, fontSize: 40, transform: `scale(${scale})`}}>
    {Array.from(new Set([...before.keys(), ...after.keys()])).map(id => {
      const from = before.get(id);
      const to = after.get(id);
      const token = to ?? from;
      const center = from && to ? from.center + (to.center - from.center) * progress : token.center;
      const opacity = from && to ? 1 : to ? progress : 1 - progress;
      const offset = from && to ? 0 : to ? 20 * (1 - progress) : -20 * progress;
      return <span key={id} style={{position: 'absolute', left: center, top: offset, opacity, whiteSpace: 'nowrap', transform: 'translate(-50%, -50%)'}}
        dangerouslySetInnerHTML={{__html: render(token.tex)}} />;
    })}
  </div>;
}

